Here's the function with debug logging. It logs the patient ID and the names of the changed fields, not the field values, because patient data is sensitive. It also logs save failures with the error and rethrows so the caller's behavior doesn't change.

```js
async function updatePatient(patient, changes) {
  const updated = { ...patient, ...changes };
  const context = {
    patientId: patient.id,
    changedFields: Object.keys(changes),
  };

  console.debug('[updatePatient] saving', context);
  try {
    await db.patients.save(updated);
  } catch (err) {
    console.error('[updatePatient] save failed', {
      ...context,
      errorName: err.name,
      errorMessage: err.message,
      stack: err.stack,
    });
    throw err;
  }
  console.debug('[updatePatient] saved', context);

  return updated;
}
```

